var t=`0358-kaiserschmarrn`;var s=`world-0358`;var a=`AT`;var n=`western-europe`;var r=4;var o=27;var l={en:`Kaiserschmarrn`,ua:`Кайзершмарн`};var u={en:`A traditional Austria dish made with all-purpose flour, whole cow milk, chicken egg, raisin. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Австрія. Основні інгредієнти: пшеничне борошно універсальне, цільне коров'яче молоко, куряче яйце, родзинки. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:9,i:[[`all-purpose-flour`,210,`g`],[`whole-cow-milk`,320,`ml`],[`chicken-egg`,4,`pcs`],[`white-granulated-sugar`,65,`g`],[`table-salt`,2,`g`],[`vanilla-extract`,4,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`unsalted-butter`,100,`g`],[`raisin`,85,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,65,`g`],[`apple-sauce`,210,`g`]]}];var h={slug:t,id:s,country:`AT`,region:n,servings:4,minutes:27,title:l,text:u,steps:g};export{a as country,h as default,s as id,o as minutes,n as region,r as servings,t as slug,g as steps,u as text,l as title};